local a=require("fcs.io.hwconfig")local b=require("fcs.io.tuningdefaults")local c={FILES={devbind="eh2_devbind.tbl",senscal="eh2_senscal.tbl",tuning="eh2_tuning.tbl",fuelcal="eh2_fuelcal.tbl"}}function c.defaults(d)local e=a.defaults()if d=="devbind"then return{thrusters=e.thrusters,sensors=e.sensors,fuelRelay=e.fuelRelay}end;if d=="senscal"then return e.bindings end;if d=="tuning"then return b.get()end;if d=="fuelcal"then return{fuel=require("fcs.fueltable").default}end;error("unknown cfg kind: "..tostring(d))end;function c.merge(d,f)return a.merge(f or{},c.defaults(d))end;function c.validate(d,g)if type(g)~="table"then return false,"not a table"end;local h=({devbind={"thrusters","sensors"},senscal={"signPitch","signHeading"},tuning={"gains","caps","feel"},fuelcal={"fuel"}})[d]for i,j in ipairs(h or{})do if g[j]==nil then return false,"missing "..j end end;return true end;function c.load(d,k)local l=k(c.FILES[d])if l==nil then return c.merge(d,{}),false,nil end;local f=textutils.unserialise(l)if type(f)~="table"then return c.merge(d,{}),true,"unparseable"end;return c.merge(d,f),true,nil end;function c.save(d,g,m)return m(c.FILES[d],textutils.serialise(g))end;function c.splitLegacy(n)return{devbind={thrusters=n.thrusters,sensors=n.sensors,fuelRelay=n.fuelRelay},senscal=n.bindings}end;function c.assembleHw(o,p)return{thrusters=o.thrusters,sensors=o.sensors,fuelRelay=o.fuelRelay,bindings=p}end;function c.tryAssemble(k)local q,r,s=c.load("devbind",k)local t,u,v=c.load("senscal",k)if s or v then return nil,s or v end;if not r and not u then return nil,nil end;return c.assembleHw(q,t)end;return c